-- Isolated synthetic database only. The existing discussion is the only message source.
begin;
create function pg_temp.discussion_items(project uuid) returns jsonb language sql as $$select coalesce((select x->'activities' from jsonb_array_elements(public.get_my_chat_directory())x where x->>'project_id'=project::text),'[]')$$;
create or replace function pg_temp.require(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Prompt39 assertion failed: %',label;end if;end$$;
do $$
declare owner uuid:=gen_random_uuid();assigned uuid:=gen_random_uuid();reviewer uuid:=gen_random_uuid();stranger uuid:=gen_random_uuid();p uuid:=gen_random_uuid();other_p uuid:=gen_random_uuid();task uuid:=gen_random_uuid();other_task uuid:=gen_random_uuid();period uuid;todo uuid;doing uuid;review uuid;done uuid;message uuid:=gen_random_uuid();second_message uuid:=gen_random_uuid();attachment uuid:=gen_random_uuid();seen bigint;next_seen bigint;items jsonb;before_comments bigint;failed boolean;v integer;
begin
 perform set_config('request.jwt.claim.sub','',true);
 insert into profiles(id,full_name)values(owner,'Same name'),(assigned,'Same name'),(reviewer,'Reviewer'),(stranger,'Nonparticipant');
 insert into projects(id,owner_id,title,slug,status)values(p,owner,'Discussion test','p39-'||p,'in_progress'),(other_p,stranger,'Other project','p39-'||other_p,'in_progress');
 insert into project_members(project_id,user_id,role,status)values(p,assigned,'member','active'),(p,reviewer,'member','active'),(p,stranger,'member','active');
 insert into project_recruitment_roles(project_id,user_id,level)values(p,reviewer,'reviewer');
 select id into period from activity_periods where project_id=p and is_active;
 if period is null then insert into activity_periods(project_id,name,is_active,created_by)values(p,'2026.2',true,owner)returning id into period;end if;
 select id into todo from activity_stages where project_id=p and kind='todo' limit 1;select id into doing from activity_stages where project_id=p and kind='doing' limit 1;select id into review from activity_stages where project_id=p and kind='review' limit 1;select id into done from activity_stages where project_id=p and kind='done' limit 1;
 insert into activity_tasks(id,project_id,period_id,title,stage_id,assignees,reviewer_id,requires_review)values(task,p,period,'Unique discussion title',todo,array[assigned],reviewer,true),(other_task,p,period,'No discussion',doing,array[assigned],reviewer,false);
 execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',assigned::text,true);
 perform pg_temp.require(jsonb_array_length(pg_temp.discussion_items(p))=0,'todo without messages excluded');
 perform set_config('request.jwt.claim.sub',owner::text,true);perform send_activity_discussion(task,'First received message',message,null,false);
 perform set_config('request.jwt.claim.sub',assigned::text,true);items:=pg_temp.discussion_items(p);
 perform pg_temp.require(jsonb_array_length(items)=1 and items->0->>'id'=task::text and (items->0->>'unread_count')::int=1,'todo with received message included once');
 select (get_activity_dialog(task,p,null)->'details'->'comments'->0->>'discussion_sequence')::bigint into seen;
 perform pg_temp.require(mark_activity_discussion_read(task,seen),'visible watermark recorded');
 perform pg_temp.require(not mark_activity_discussion_read(task,seen),'same read from another surface is idempotent');
 perform send_activity_discussion(task,'Own reply',second_message,message,false);items:=pg_temp.discussion_items(p);
 perform pg_temp.require((items->0->>'unread_count')::int=0 and items->0->>'preview'='Own reply','own message does not increment unread; preview refreshed');
 select (c->>'discussion_sequence')::bigint into next_seen from jsonb_array_elements(get_activity_dialog(task,p,null)->'details'->'comments')c where c->>'id'=second_message::text;
 perform mark_activity_discussion_read(task,next_seen);perform mark_activity_discussion_read(task,seen);
 perform pg_temp.require((select last_read_sequence=next_seen from activity_discussion_reads where task_id=task and user_id=assigned),'older surface cannot regress watermark');
 perform set_config('request.jwt.claim.sub',owner::text,true);perform send_activity_discussion(task,'Another received message',gen_random_uuid(),null,false);
 perform set_config('request.jwt.claim.sub',assigned::text,true);items:=pg_temp.discussion_items(p);perform pg_temp.require((items->0->>'unread_count')::int=1,'only new received message unread');
 v:=(get_activity_dialog(task,p,null)->'tasks'->0->>'version')::int;
 perform mutate_activity(p,'move',jsonb_build_object('id',task,'version',v,'stage_id',doing));
 perform pg_temp.require(pg_temp.discussion_items(p)->0->>'kind'='doing','doing discussion included');
 v:=(get_activity_dialog(task,p,null)->'tasks'->0->>'version')::int;perform mutate_activity(p,'move',jsonb_build_object('id',task,'version',v,'stage_id',review));
 perform pg_temp.require(jsonb_array_length(pg_temp.discussion_items(p))=0,'review excluded including its unread');
 perform set_config('request.jwt.claim.sub',reviewer::text,true);v:=(get_activity_dialog(task,p,null)->'tasks'->0->>'version')::int;perform mutate_activity(p,'return',jsonb_build_object('id',task,'version',v,'reason','Adjust the evidence'));
 perform set_config('request.jwt.claim.sub',assigned::text,true);items:=pg_temp.discussion_items(p);perform pg_temp.require(jsonb_array_length(items)=1 and (items->0->>'unread_count')::int=1,'returned discussion reappears with original unread state');
 perform pg_temp.require(jsonb_array_length(get_activity_dialog(task,p,null)->'details'->'comments')=3,'one canonical discussion across accesses');
 execute 'reset role';insert into activity_comment_attachments(id,comment_id,task_id,project_id,path,filename,mime,size,sha256)values(attachment,message,task,p,'synthetic/'||attachment,'evidence.txt','text/plain',10,repeat('a',64));
 execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',stranger::text,true);
 perform pg_temp.require(jsonb_array_length(pg_temp.discussion_items(p))=0,'mere project membership does not expose activity discussions');
 failed:=false;begin perform get_activity_dialog(task,p,null);exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'manipulated dialog ID rejected');
 failed:=false;begin perform get_activity_details(p,task,null);exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'legacy details RPC cannot bypass participant authorization');
 failed:=false;begin perform mutate_activity(p,'comment',jsonb_build_object('id',task,'body','Forbidden'));exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'legacy mutation cannot bypass participant authorization');
 failed:=false;begin perform mark_activity_discussion_read(task,seen);exception when raise_exception then failed:=true;end;perform pg_temp.require(failed,'nonparticipant cannot mark discussion read');
 perform pg_temp.require((select count(*)=0 from activity_comment_attachments where id=attachment),'attachment RLS rejects nonparticipant within same project');
 perform set_config('request.jwt.claim.sub',reviewer::text,true);perform pg_temp.require(activity_private.can_discuss(task),'designated reviewer authorized');
 execute 'reset role';update activity_tasks set reviewer_id=null where id=task;
 execute 'set local role authenticated';perform pg_temp.require(not activity_private.can_discuss(task),'reviewer role alone does not grant every discussion');
 perform set_config('request.jwt.claim.sub',owner::text,true);perform pg_temp.require(jsonb_array_length(pg_temp.discussion_items(p))=1,'manager authorized');
 execute 'reset role';update activity_tasks set stage_id=done where id=task;
 execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',assigned::text,true);perform pg_temp.require(jsonb_array_length(pg_temp.discussion_items(p))=0,'done discussion excluded');
 execute 'reset role';update activity_tasks set stage_id=doing where id=task;select count(*) into before_comments from activity_comments where task_id=task;update projects set status='completed' where id=p;
 execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',assigned::text,true);perform pg_temp.require(jsonb_array_length(pg_temp.discussion_items(p))=0,'finalized project has no active discussion');
 perform pg_temp.require((get_activity_dialog(task,p,null)->>'projectReadOnly')::boolean and jsonb_array_length(get_activity_dialog(task,p,null)->'details'->'comments')=before_comments,'historical conversation remains read-only and intact');
 perform pg_temp.require((select count(*)=1 from activity_comment_attachments where id=attachment),'historical evidence preserved and authorized');
end$$;
rollback;
